// Pseudo-code for W4A16 inner loop, one K-block of BLOCK_K = 128 INT4 weights per row.
// weights_packed: two INT4 values per byte, symmetric per-group scale (group_size 128).
// scale: shape (out_rows, K / 128), FP16.
// Loading one 64-byte chunk (128 INT4 values).

uint8_t packed[64];   // 64 bytes = 128 INT4 weights
load_from_gmem(packed, weights_packed + row * K_bytes + kg * 64);

half w[128];
for (int i = 0; i < 64; ++i) {
    int lo = (int8_t)((packed[i] << 4) >> 4);   // sign-extend low nibble to int8 in [-8,7]
    int hi = (int8_t)(packed[i]) >> 4;          // sign-extend high nibble
    w[2*i    ] = __int2half_rn(lo);
    w[2*i + 1] = __int2half_rn(hi);
}
// Apply per-group scale (one scalar for this entire 128-element block).
half s = scale[row * (K/128) + kg];
for (int i = 0; i < 128; ++i) w[i] = __hmul(w[i], s);
// w[128] is now dequantized FP16 weights; feed to FP16 Tensor Core.
